qss:
/* ===== PS01-TERM 结构观感（v3.42.0，随深浅主题）===== */
/* 全局等宽字体（tmux 手感）*/
QMenuBar, QMenu, QStatusBar, QToolBar, QToolBar QToolButton,
QMainWindow #tabstrip QTabBar, QLineEdit, QComboBox {
  font-family: "Consolas", "Cascadia Mono", "Microsoft YaHei Mono", monospace;
}
/* 全直角 */
QToolButton, QMenu, QTabBar::tab, QLineEdit, QComboBox, QPushButton {
  border-radius: 0;
}
/* 菜单：tmux 式实心强调高亮（浅=绿底白字 / 深=绿底黑字）*/
QMenu {
  border-radius: 0;
  padding: 3px;
}
QMenu::item {
  border-radius: 0;
}
QMenu::item:selected {
  background: {menu_sel_bg};
  color: {menu_sel_text};
}
/* 页签：方格式分隔 + 当前项强调色 */
QMainWindow #tabstrip QTabBar::tab:!selected {
  border-radius: 0;
  border-right: 1px solid {border};
}
QMainWindow #tabstrip QTabBar::tab:selected {
  color: {tab_sel_text};
  border-top: 2px solid {accent};
}
QMenuBar::item {
  border-radius: 0;
  font-weight: 600;
}
QMenuBar::item:selected {
  background: {hover_bg};
  color: {hover_text};
}
